public static Food[] priceRetrieve(Food[][] items) {
    Food[] lowest = new Food[items.length];
    Double[][] prices = new Double[items.length][items.length];   // Fix 1

    for (int i = 0; i < items.length; ++i)
        for (int j = 0; j < items.length; ++j)
            if (items[i][j] != null)                              // Fix 2
                prices[i][j] = items[i][j].calculatePrice();

    int lowestRowIndex = -1, lowestColIndex = -1;
    double lowestRowAvg = 0, lowestColAvg = 0;

    for (int i = 0; i < items.length; ++i) {
        double totalRow = 0, totalCol = 0;
        int countRow = 0, countCol = 0;
        boolean rowInvalid = false, colInvalid = false;

        for (int j = 0; j < items.length; ++j) {
            if (prices[i][j] != null) {
                if (prices[i][j] <= 0) rowInvalid = true;
                else { totalRow += prices[i][j]; countRow++; }
            }
            if (prices[j][i] != null) {
                if (prices[j][i] <= 0) colInvalid = true;
                else { totalCol += prices[j][i]; countCol++; }
            }
        }
        if (!rowInvalid && countRow > 0 &&                        // Fix 3
           (lowestRowAvg == 0 || totalRow / countRow < lowestRowAvg)) {
            lowestRowAvg = totalRow / countRow;
            lowestRowIndex = i;
        }
        if (!colInvalid && countCol > 0 &&                        // Fix 3
           (lowestColAvg == 0 || totalCol / countCol < lowestColAvg)) {
            lowestColAvg = totalCol / countCol;
            lowestColIndex = i;
        }
    }

    for (int i = 0; i < items.length; ++i) {
        if (lowestRowAvg < lowestColAvg) lowest[i] = items[lowestRowIndex][i];
        else                             lowest[i] = items[i][lowestColIndex];
    }
    return lowest;
}
```

